import './styles.css';
import { useState } from 'react';

interface Question {
  id: number;
  scenario: string;
  aiResponse: string;
  isHallucination: boolean;
  explanation: string;
  redFlags: string[];
  verificationTip: string;
}

const questions: Question[] = [
  {
    id: 1,
    scenario: 'You ask an AI: "Who wrote the novel \'The Midnight Library\'?"',
    aiResponse: 'The Midnight Library was written by Matt Haig, published in 2020. It became a bestseller and was selected for various book clubs.',
    isHallucination: false,
    explanation: 'This is accurate! Matt Haig did write The Midnight Library, and it was published in 2020.',
    redFlags: [],
    verificationTip: 'For book information, you can verify on Goodreads, Amazon, or the publisher\'s website.',
  },
  {
    id: 2,
    scenario: 'You ask an AI: "Tell me about the Henderson Prize for Mathematics."',
    aiResponse: 'The Henderson Prize for Mathematics is awarded annually by the American Mathematical Society to recognize outstanding contributions to number theory. Established in 1987, it carries a $25,000 award. Recent recipients include Dr. Sarah Chen (2022) and Prof. Michael Okonkwo (2021).',
    isHallucination: true,
    explanation: 'This is a hallucination! There is no "Henderson Prize for Mathematics." The AI invented the award, its history, and the recipients with plausible-sounding details.',
    redFlags: [
      'Very specific but unverifiable names and dates',
      'The prize doesn\'t appear in searches',
      'Names of "recipients" don\'t match real mathematicians',
    ],
    verificationTip: 'Always verify awards and prizes through official organization websites. Major math prizes are well-documented.',
  },
  {
    id: 3,
    scenario: 'You ask an AI: "What is the capital of Australia?"',
    aiResponse: 'The capital of Australia is Canberra. Many people mistakenly think it\'s Sydney or Melbourne, which are larger cities, but Canberra was purpose-built to serve as the capital.',
    isHallucination: false,
    explanation: 'This is correct! Canberra is indeed the capital of Australia, and it was purpose-built for that role.',
    redFlags: [],
    verificationTip: 'Basic geography facts can be verified with any encyclopedia or atlas.',
  },
  {
    id: 4,
    scenario: 'You ask an AI: "What did Einstein say about compound interest?"',
    aiResponse: 'Albert Einstein famously called compound interest "the eighth wonder of the world," stating that "those who understand it, earn it; those who don\'t, pay it." This quote appears in several financial publications.',
    isHallucination: true,
    explanation: 'This is a hallucination! There\'s no documented evidence that Einstein ever said this. This quote has been misattributed to him for decades.',
    redFlags: [
      'Famous "quotes" are often misattributed',
      'No primary source citation',
      'The quote sounds too perfect for modern financial advice',
    ],
    verificationTip: 'For famous quotes, check Quote Investigator or primary biographical sources. Many viral quotes are misattributed.',
  },
  {
    id: 5,
    scenario: 'You ask an AI: "What is photosynthesis?"',
    aiResponse: 'Photosynthesis is the process by which plants convert light energy into chemical energy. Plants absorb carbon dioxide and water, and using sunlight, produce glucose and oxygen. The basic equation is: 6CO2 + 6H2O + light energy → C6H12O6 + 6O2.',
    isHallucination: false,
    explanation: 'This is accurate! The explanation and chemical equation for photosynthesis are correct.',
    redFlags: [],
    verificationTip: 'Scientific facts can be verified in textbooks or educational resources like Khan Academy.',
  },
  {
    id: 6,
    scenario: 'You ask an AI: "Tell me about the 2019 study on social media and sleep by Dr. Jennifer Walsh."',
    aiResponse: 'Dr. Jennifer Walsh\'s 2019 study published in the Journal of Digital Health found that adolescents who used social media for more than 3 hours daily had 47% higher rates of sleep disturbance. The study surveyed 2,340 participants across five U.S. states.',
    isHallucination: true,
    explanation: 'This is likely a hallucination! The specific researcher, study details, and statistics are fabricated. The AI generated plausible-sounding research that doesn\'t exist.',
    redFlags: [
      'Very specific statistics that can\'t be verified',
      'Named researcher doesn\'t appear in searches',
      'Journal name is generic and vague',
      'No DOI or link to the actual study',
    ],
    verificationTip: 'Research papers should be verifiable on Google Scholar, PubMed, or the journal\'s website. Always check for DOIs.',
  },
  {
    id: 7,
    scenario: 'You ask an AI: "When did World War II end?"',
    aiResponse: 'World War II ended in 1945. Germany surrendered on May 8, 1945 (V-E Day), and Japan surrendered on September 2, 1945 (V-J Day), following the atomic bombings of Hiroshima and Nagasaki.',
    isHallucination: false,
    explanation: 'This is accurate! These are the correct dates for the end of World War II in both theaters.',
    redFlags: [],
    verificationTip: 'Major historical events are well-documented and easily verifiable.',
  },
  {
    id: 8,
    scenario: 'You ask an AI for legal advice: "What are the regulations for nonprofits in Kenya?"',
    aiResponse: 'Kenyan nonprofits are regulated under the Public Benefits Organizations Act of 2013. Organizations must register with the PBO Authority, submit annual returns by March 31st, and maintain a minimum of 5 board members. Foreign funding over $50,000 requires special approval.',
    isHallucination: true,
    explanation: 'This contains hallucinations! While the PBO Act exists, the specific requirements mentioned (dates, board numbers, funding thresholds) may be inaccurate or made up. Legal information requires verification with current official sources.',
    redFlags: [
      'Very specific legal requirements that could change',
      'No citation to official sources',
      'Regulations vary and update frequently',
    ],
    verificationTip: 'Legal requirements MUST be verified with official government sources or qualified legal counsel. Never rely on AI for legal advice.',
  },
];

function QuestionCard({ 
  question, 
  userAnswer, 
  onAnswer, 
  showResult 
}: {
  question: Question;
  userAnswer: boolean | null;
  onAnswer: (answer: boolean) => void;
  showResult: boolean;
}) {
  const isCorrect = userAnswer === question.isHallucination;

  return (
    <div className="question-card">
      <div className="scenario">
        <span className="scenario-label">Scenario</span>
        <p>{question.scenario}</p>
      </div>

      <div className="ai-response">
        <span className="response-label">AI Response</span>
        <p>{question.aiResponse}</p>
      </div>

      {!showResult ? (
        <div className="answer-buttons">
          <button
            className={`answer-btn safe ${userAnswer === false ? 'selected' : ''}`}
            onClick={() => onAnswer(false)}
          >
            <span className="btn-icon">✓</span>
            Looks Accurate
          </button>
          <button
            className={`answer-btn suspicious ${userAnswer === true ? 'selected' : ''}`}
            onClick={() => onAnswer(true)}
          >
            <span className="btn-icon">⚠</span>
            Possible Hallucination
          </button>
        </div>
      ) : (
        <div className={`result ${isCorrect ? 'correct' : 'incorrect'}`}>
          <div className="result-header">
            <span className="result-icon">{isCorrect ? '✓' : '✗'}</span>
            <span className="result-text">
              {isCorrect ? 'Correct!' : 'Not quite!'}
            </span>
          </div>

          <div className="result-truth">
            <strong>The truth:</strong> {question.isHallucination ? 'This IS a hallucination' : 'This is accurate'}
          </div>

          <p className="explanation">{question.explanation}</p>

          {question.redFlags.length > 0 && (
            <div className="red-flags">
              <strong>Red flags to watch for:</strong>
              <ul>
                {question.redFlags.map((flag, i) => (
                  <li key={i}>{flag}</li>
                ))}
              </ul>
            </div>
          )}

          <div className="verification-tip">
            <span className="tip-label">Verification tip:</span>
            <p>{question.verificationTip}</p>
          </div>
        </div>
      )}
    </div>
  );
}

function Results({ score, total, onRestart }: {
  score: number;
  total: number;
  onRestart: () => void;
}) {
  const percentage = Math.round((score / total) * 100);
  let message = '';
  let emoji = '';

  if (percentage >= 90) {
    message = 'Excellent! You\'re a hallucination detective!';
    emoji = '🕵️';
  } else if (percentage >= 70) {
    message = 'Great job! You\'ve got a good eye for AI errors.';
    emoji = '👍';
  } else if (percentage >= 50) {
    message = 'Good start! With practice, you\'ll spot them faster.';
    emoji = '📚';
  } else {
    message = 'Keep learning! AI can be very convincing.';
    emoji = '💪';
  }

  return (
    <div className="results-panel">
      <div className="results-emoji">{emoji}</div>
      <h2>{message}</h2>
      <p className="score-text">
        You correctly identified <strong>{score}</strong> out of <strong>{total}</strong> scenarios
      </p>
      <div className="score-bar">
        <div className="score-fill" style={{ width: `${percentage}%` }} />
      </div>
      <p className="percentage">{percentage}%</p>

      <div className="takeaway">
        <h3>Key Takeaway</h3>
        <p>
          AI hallucinations often sound confident and include specific details. The best defense is always verification - especially for names, statistics, quotes, and recent events.
        </p>
      </div>

      <button className="restart-btn" onClick={onRestart}>
        Try Again
      </button>
    </div>
  );
}

export default function App() {
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState<(boolean | null)[]>(new Array(questions.length).fill(null));
  const [showResults, setShowResults] = useState<boolean[]>(new Array(questions.length).fill(false));
  const [quizComplete, setQuizComplete] = useState(false);

  const handleAnswer = (answer: boolean) => {
    const newAnswers = [...answers];
    newAnswers[currentQuestion] = answer;
    setAnswers(newAnswers);
  };

  const handleCheck = () => {
    const newShowResults = [...showResults];
    newShowResults[currentQuestion] = true;
    setShowResults(newShowResults);
  };

  const handleNext = () => {
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
    } else {
      setQuizComplete(true);
    }
  };

  const handleRestart = () => {
    setCurrentQuestion(0);
    setAnswers(new Array(questions.length).fill(null));
    setShowResults(new Array(questions.length).fill(false));
    setQuizComplete(false);
  };

  const score = answers.reduce((acc, answer, index) => {
    return acc + (answer === questions[index].isHallucination ? 1 : 0);
  }, 0);

  if (quizComplete) {
    return (
      <div className="app">
        <Results score={score} total={questions.length} onRestart={handleRestart} />
      </div>
    );
  }

  const question = questions[currentQuestion];
  const hasAnswered = answers[currentQuestion] !== null;
  const isRevealed = showResults[currentQuestion];

  return (
    <div className="app">
      <div className="header">
        <h1>Spot the Hallucination</h1>
        <p className="subtitle">
          Can you tell when AI is making things up?
        </p>
      </div>

      <div className="progress">
        <div className="progress-bar">
          <div 
            className="progress-fill" 
            style={{ width: `${((currentQuestion + 1) / questions.length) * 100}%` }}
          />
        </div>
        <span className="progress-text">
          Question {currentQuestion + 1} of {questions.length}
        </span>
      </div>

      <QuestionCard
        question={question}
        userAnswer={answers[currentQuestion]}
        onAnswer={handleAnswer}
        showResult={isRevealed}
      />

      <div className="nav-buttons">
        {!isRevealed ? (
          <button
            className="check-btn"
            onClick={handleCheck}
            disabled={!hasAnswered}
          >
            Check Answer
          </button>
        ) : (
          <button className="next-btn" onClick={handleNext}>
            {currentQuestion < questions.length - 1 ? 'Next Question' : 'See Results'}
          </button>
        )}
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
  min-height: 100vh;
  padding: 2rem 1rem;
}

.app {
  max-width: 700px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 2rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 1rem;
}

.progress {
  margin-bottom: 1.5rem;
}

.progress-bar {
  height: 8px;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 0.5rem;
}

.progress-fill {
  height: 100%;
  background: white;
  border-radius: 4px;
  transition: width 0.3s ease;
}

.progress-text {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.875rem;
}

.question-card {
  background: white;
  border-radius: 1rem;
  padding: 1.5rem;
  margin-bottom: 1rem;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.scenario {
  margin-bottom: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid #e5e7eb;
}

.scenario-label {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 600;
  color: #6b7280;
  text-transform: uppercase;
  margin-bottom: 0.5rem;
}

.scenario p {
  color: #374151;
  font-size: 0.95rem;
  line-height: 1.5;
}

.ai-response {
  background: #f9fafb;
  border: 1px solid #e5e7eb;
  border-radius: 0.75rem;
  padding: 1rem;
  margin-bottom: 1rem;
}

.response-label {
  display: inline-block;
  font-size: 0.7rem;
  font-weight: 600;
  color: #3b82f6;
  background: #dbeafe;
  padding: 0.15rem 0.5rem;
  border-radius: 0.25rem;
  margin-bottom: 0.5rem;
}

.ai-response p {
  color: #1f2937;
  font-size: 0.95rem;
  line-height: 1.6;
}

.answer-buttons {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}

.answer-btn {
  padding: 1rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.75rem;
  background: white;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9rem;
  font-weight: 600;
}

.btn-icon {
  font-size: 1.5rem;
}

.answer-btn.safe:hover, .answer-btn.safe.selected {
  border-color: #10b981;
  background: #ecfdf5;
  color: #047857;
}

.answer-btn.suspicious:hover, .answer-btn.suspicious.selected {
  border-color: #f59e0b;
  background: #fffbeb;
  color: #b45309;
}

.result {
  padding: 1rem;
  border-radius: 0.75rem;
  margin-top: 1rem;
}

.result.correct {
  background: #ecfdf5;
  border: 1px solid #10b981;
}

.result.incorrect {
  background: #fef2f2;
  border: 1px solid #ef4444;
}

.result-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.result-icon {
  font-size: 1.25rem;
}

.result.correct .result-icon { color: #10b981; }
.result.incorrect .result-icon { color: #ef4444; }

.result-text {
  font-weight: 700;
  font-size: 1.1rem;
}

.result.correct .result-text { color: #047857; }
.result.incorrect .result-text { color: #b91c1c; }

.result-truth {
  background: white;
  padding: 0.5rem 0.75rem;
  border-radius: 0.5rem;
  margin-bottom: 0.75rem;
  font-size: 0.9rem;
}

.explanation {
  color: #374151;
  font-size: 0.9rem;
  line-height: 1.5;
  margin-bottom: 0.75rem;
}

.red-flags {
  background: #fef3c7;
  padding: 0.75rem;
  border-radius: 0.5rem;
  margin-bottom: 0.75rem;
}

.red-flags strong {
  display: block;
  font-size: 0.8rem;
  color: #b45309;
  margin-bottom: 0.5rem;
}

.red-flags ul {
  list-style: none;
  padding-left: 0;
}

.red-flags li {
  font-size: 0.85rem;
  color: #92400e;
  padding-left: 1rem;
  position: relative;
  margin-bottom: 0.25rem;
}

.red-flags li::before {
  content: '⚠';
  position: absolute;
  left: 0;
  font-size: 0.7rem;
}

.verification-tip {
  background: #dbeafe;
  padding: 0.75rem;
  border-radius: 0.5rem;
}

.tip-label {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  color: #1d4ed8;
  margin-bottom: 0.25rem;
}

.verification-tip p {
  color: #1e40af;
  font-size: 0.85rem;
  margin: 0;
}

.nav-buttons {
  display: flex;
  gap: 0.75rem;
}

.check-btn, .next-btn {
  flex: 1;
  padding: 1rem;
  border: none;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.check-btn {
  background: white;
  color: #dc2626;
}

.check-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(255, 255, 255, 0.3);
}

.check-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.next-btn {
  background: linear-gradient(135deg, #10b981, #059669);
  color: white;
}

.next-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(16, 185, 129, 0.4);
}

/* Results */
.results-panel {
  background: white;
  border-radius: 1rem;
  padding: 2rem;
  text-align: center;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.2);
}

.results-emoji {
  font-size: 4rem;
  margin-bottom: 1rem;
}

.results-panel h2 {
  color: #1f2937;
  font-size: 1.5rem;
  margin-bottom: 1rem;
}

.score-text {
  color: #6b7280;
  font-size: 1rem;
  margin-bottom: 1rem;
}

.score-text strong {
  color: #dc2626;
}

.score-bar {
  height: 12px;
  background: #e5e7eb;
  border-radius: 6px;
  overflow: hidden;
  margin-bottom: 0.5rem;
}

.score-fill {
  height: 100%;
  background: linear-gradient(90deg, #dc2626, #f87171);
  border-radius: 6px;
  transition: width 0.5s ease;
}

.percentage {
  color: #dc2626;
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 1.5rem;
}

.takeaway {
  background: #fef2f2;
  border-radius: 0.75rem;
  padding: 1rem;
  margin-bottom: 1.5rem;
  text-align: left;
}

.takeaway h3 {
  color: #991b1b;
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
}

.takeaway p {
  color: #7f1d1d;
  font-size: 0.9rem;
  line-height: 1.5;
}

.restart-btn {
  padding: 1rem 2rem;
  background: linear-gradient(135deg, #dc2626, #b91c1c);
  color: white;
  border: none;
  border-radius: 0.75rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.restart-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 15px rgba(220, 38, 38, 0.4);
}

@media (max-width: 500px) {
  .answer-buttons {
    grid-template-columns: 1fr;
  }
}
